<script setup>
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {api,notify} from '../lib'
import Icon from './Icon.vue'
import RoundedSelect from './RoundedSelect.vue'
import PageJumpInput from './PageJumpInput.vue'
import PosterImage from './PosterImage.vue'
const result=ref({items:[],total:0,page:1,pages:1}),query=ref(''),source=ref(''),loading=ref(false),expanded=ref(''),pageInput=ref(1)
let alive=true,ticket=0,timer
async function load(page=1){const run=++ticket;loading.value=true;try{const data=await api('/archives/cache?'+new URLSearchParams({q:query.value,source:source.value,page:String(page)}));if(alive&&run===ticket){result.value=data;pageInput.value=data.page}}catch(e){if(alive&&run===ticket)notify(e.message,true)}finally{if(alive&&run===ticket)loading.value=false}}
watch([query,source],()=>{clearTimeout(timer);timer=setTimeout(()=>load(),250)})
onMounted(load);onUnmounted(()=>{alive=false;ticket++;clearTimeout(timer)})
const time=value=>value?new Date(value).toLocaleString():''
</script>
<template><section class="archive-panel cache-archive-panel" aria-label="缓存档案"><header class="archive-toolbar"><RoundedSelect v-model="source" label="缓存来源" :options="[{value:'',label:'全部缓存'},{value:'tmdb',label:'TMDB作品'},{value:'directory',label:'存储目录'}]"/><span class="archive-count" role="status">{{result.total}} 项</span><button class="icon-btn" aria-label="刷新缓存档案" :disabled="loading" @click="load(result.page)"><Icon name="RefreshCw" :class="{spin:loading}"/></button><div class="search-field"><Icon name="Search"/><input v-model="query" aria-label="搜索缓存" placeholder="搜索作品、TMDB ID或目录"/></div></header><p v-if="!result.items.length" class="small-empty">{{loading?'正在读取缓存…':'暂无有效缓存'}}</p><article v-for="item in result.items" :key="item.id" class="cache-archive-row"><div class="cache-record-main"><PosterImage v-if="item.source==='tmdb'" class="cache-record-poster" :src="item.poster" :title="item.title" :kind="item.kind"/><Icon v-else name="Folder" :size="32"/><div><h3>{{item.title}}</h3><p v-if="item.source==='tmdb'">{{item.kind==='tv'?'剧集':'电影'}} · TMDB {{item.tmdb}} · {{item.release||'上映时间未知'}}</p><p v-else>{{item.path||'根目录'}} · {{item.count}} 项</p><p class="cache-record-overview">{{item.overview|| (item.source==='tmdb'?'暂无简介':'目录列表缓存')}}</p><small>有效至 {{time(item.expires)}}</small></div><button v-if="item.source==='directory'" class="text-btn" :aria-expanded="expanded===item.id" @click="expanded=expanded===item.id?'':item.id"><Icon :name="expanded===item.id?'ChevronUp':'ChevronDown'"/>缓存结果</button></div><div v-if="expanded===item.id" class="cache-directory-results"><p v-for="file in item.files" :key="file.id"><Icon :name="file.isDir?'Folder':'File'" :size="16"/><span :data-tooltip="file.name" data-tooltip-stationary>{{file.name}}</span></p><small v-if="item.count>item.files.length">预览前 {{item.files.length}} 项，共 {{item.count}} 项</small></div></article><form v-if="result.pages>1" class="archive-pagination" @submit.prevent="load(pageInput)"><button type="button" class="btn" :disabled="result.page<=1||loading" @click="load(result.page-1)">上一页</button><span>{{result.page}} / {{result.pages}}</span><button type="button" class="btn" :disabled="result.page>=result.pages||loading" @click="load(result.page+1)">下一页</button><PageJumpInput v-model="pageInput" :pages="result.pages" aria-label="缓存跳转页码"/><button class="icon-btn" aria-label="跳转缓存页码"><Icon name="CornerDownLeft"/></button></form></section></template>
<style scoped>.cache-archive-row{padding:18px;border-bottom:1px solid var(--border)}.cache-record-main{display:flex;align-items:center;gap:18px;min-width:0}.cache-record-poster{width:72px;height:108px;border-radius:7px;flex:none}.cache-record-main>svg{flex:none;color:var(--amber)}.cache-record-main>div{min-width:0;flex:1}.cache-record-main h3{font-size:16px;margin:0 0 8px;overflow-wrap:anywhere}.cache-record-main p{font-size:13px;margin:6px 0;overflow-wrap:anywhere}.cache-record-main small{color:var(--muted);font-size:12px}.cache-record-overview{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;color:var(--muted);line-height:1.65}.cache-directory-results{max-height:320px;overflow:auto;scrollbar-width:none;padding:8px 0}.cache-directory-results p{display:flex;gap:10px;align-items:center;padding:7px;margin:0;font-size:13px}.cache-directory-results span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cache-directory-results small{color:var(--muted)}@media(max-width:600px){.cache-record-main{gap:12px;flex-wrap:wrap}.cache-record-poster{width:60px;height:90px}.cache-record-main>.text-btn{margin-left:auto}.cache-archive-row{padding:14px}}</style>
